examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true })
if (open) {
    MonarchBottomSheet(
        onDismissRequest = { open = false },
        title = {{title}},
        description = {{description}},
        fullWidthContent = true,
        closeButton = true,
    ) {
        MonarchListRow(
            overlineContent = { MonarchText(text = {{details.0.term}}) },
            headlineContent = { MonarchText(text = {{details.0.value}}) },
        )
        MonarchListRow(
            overlineContent = { MonarchText(text = {{details.1.term}}) },
            headlineContent = { MonarchText(text = {{details.1.value}}) },
        )
        MonarchListRow(
            overlineContent = { MonarchText(text = {{details.2.term}}) },
            headlineContent = { MonarchText(text = {{details.2.value}}) },
        )
        Row(
            modifier = Modifier.padding(MonarchTheme.spacing.space4),
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            MonarchButton(text = {{close}}, onClick = { open = false })
            MonarchButton(text = {{action}}, onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        }
    }
}

examples.code:
MonarchButton(text = "Open details", onClick = { open = true })
if (open) {
    MonarchBottomSheet(
        onDismissRequest = { open = false },
        title = "Invoice INV-1042",
        description = "Sent on 12 March to the billing contact.",
        fullWidthContent = true,
        closeButton = true,
    ) {
        MonarchListRow(
            overlineContent = { MonarchText(text = "Status") },
            headlineContent = { MonarchText(text = "Awaiting payment") },
        )
        MonarchListRow(
            overlineContent = { MonarchText(text = "Due") },
            headlineContent = { MonarchText(text = "26 March") },
        )
        MonarchListRow(
            overlineContent = { MonarchText(text = "Owner") },
            headlineContent = { MonarchText(text = "Priya Raman") },
        )
        Row(
            modifier = Modifier.padding(MonarchTheme.spacing.space4),
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            MonarchButton(text = "Close", onClick = { open = false })
            MonarchButton(text = "Send reminder", onClick = { open = false }, variant = MonarchButtonVariant.Primary)
        }
    }
}

MonarchButton(text = "Add a note", onClick = { open = true })
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = "Add a note") {
        // Column is a layout scope of its own: name the sheet to close it from inside.
        val sheet = this
        Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
            MonarchTextField(value = note, onValueChange = { note = it }, label = "Note", singleLine = false)
            MonarchButton(
                text = "Save",
                onClick = { sheet.dismiss() },
                modifier = Modifier.fillMaxWidth(),
                variant = MonarchButtonVariant.Primary,
            )
        }
    }
}

ModalNavigationDrawer(
    drawerState = drawerState,
    drawerContent = {
        ModalDrawerSheet {
            Column(
                modifier = Modifier.padding(MonarchTheme.spacing.space4),
                verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            ) {
                MonarchText(text = "Filters", style = MonarchTextStyle.Heading)
                MonarchCheckboxRow(checked = true, onCheckedChange = {}, label = "Only mine")
                MonarchButton(text = "Done", onClick = { scope.launch { drawerState.close() } })
            }
        }
    },
) {
    MonarchButton(text = "Filters", onClick = { scope.launch { drawerState.open() } })
}
